import { Component,OnInit } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { PaymentService } from './payment-info.service';
import Swal from 'sweetalert2';
import { ProfileService } from "../profile/profile.service";

@Component({
  selector: 'app-profile',
  templateUrl: './payment-info.component.html',
  styleUrl: './payment-info.component.scss'
})
export class PaymentInfo {
  paymentInfoForm: FormGroup;
  copiedAndroid = false;
  copiedIOS = false;
  constructor(private fb: FormBuilder, private PaymentService: PaymentService,
    private profileService: ProfileService
  ) {
    this.paymentInfoForm = this.fb.group({
      payee_name: ['', [Validators.required]], // URL validation
      upi_id: ['', [Validators.required]],
      payment_note: ['', [Validators.required]],
    });

    this.PaymentService.getPaymentInfoData().subscribe((data) => {
      let Obj = data.results
      this.paymentInfoForm.patchValue({
        payee_name: Obj.payee_name,
        upi_id: Obj.upi_id,
        payment_note: Obj.payment_note,
      });
    });
  }


  updateReferral() {
    if (this.paymentInfoForm.invalid) {
      return;
    }
    this.PaymentService.updatePaymentInfoData(this.paymentInfoForm.value).subscribe(
      (response) => {
        Swal.fire({
          icon: 'success',
          title: 'Updated Successfully!',
          text: 'Payment Info have been updated.',
          confirmButtonColor: '#3085d6',
          confirmButtonText: 'OK',
        });
        console.log('Payment Info updated successfully', response);
      },
      (error) => {
        console.error('Error updating referral data', error);
      }
    );
  }
  copyText(text: string, type: 'android' | 'ios'): void {
    navigator.clipboard.writeText(text).then(() => {
      if (type === 'android') {
        this.copiedAndroid = true;
        setTimeout(() => this.copiedAndroid = false, 1000);
      } else if (type === 'ios') {
        this.copiedIOS = true;
        setTimeout(() => this.copiedIOS = false, 1000);
      }
    }).catch(err => {
      console.error('Failed to copy:', err);
    });
  }
  
  
}